def allow_redirect_url(url: str) -> bool:
    cors = CorsMiddleware()
    origin = origin_from_url(url)
    parts = urlparse(url)
    if not cors_conf.CORS_ALLOW_ALL_ORIGINS and not cors.origin_found_in_white_lists(
        origin, parts
    ):
        return False
    else:
        return True
